(function(e,t){typeof define=="function"&&define.amd?define([],t):typeof module=="object"&&module.exports?module.exports=t():e.KinesicaBookingWidgetTemplate=t()})(typeof self!="undefined"?self:this,function(){"use strict";function e(t){return`
      <div class="kinesica-booking-container ${t.options.isModal?"is-modal":"is-inline"}">
        <div class="kb-header">
          ${t.options.isModal?`<button type="button" class="kb-close-btn" aria-label="${t.t("close")}" data-action="close-modal">&times;</button>`:""}
          <h2>${t.t("title")}</h2>
          <p>${t.t("subtitle")}</p>
        </div>

        <div class="kb-stepper">
          <div class="kb-step-item active" data-step-indicator="1"><span class="kb-step-num">1</span> ${t.t("step1")}</div>
          <div class="kb-step-item" data-step-indicator="2"><span class="kb-step-num">2</span> ${t.t("step2")}</div>
          <div class="kb-step-item" data-step-indicator="3"><span class="kb-step-num">3</span> ${t.t("step3")}</div>
          <div class="kb-step-item" data-step-indicator="4"><span class="kb-step-num">4</span> ${t.t("step4")}</div>
        </div>

        <div class="kb-body">
          <div id="kb-error-banner" class="kb-error-banner"></div>

          <!-- PASO 1: PACIENTE \u2192 PROFESIONAL O T\xC9CNICA -->
          <div class="kb-step-panel active" id="kb-step-1">
            <div class="kb-section-title">${t.t("qPatient")}</div>
            <div class="kb-choice-grid" id="kb-patient-grid" ${t.options.adminMode?'style="display:none"':""}></div>

            <div id="kb-existing-box" class="kb-step1-followup" hidden>
              <div class="kb-section-title" style="font-size: 17px;">${t.t("qWho")}</div>
              <p class="kb-section-hint" id="kb-existing-hint" ${t.options.adminMode?"hidden":""}>${t.t("existingHint")}</p>
              <div class="kb-choice-grid" id="kb-existing-practitioner-grid"></div>
            </div>

            <div id="kb-new-box" class="kb-step1-followup" hidden>
              <div class="kb-section-title" style="font-size: 17px;">${t.t("qTechnique")}</div>
              <p class="kb-section-hint" id="kb-technique-hint" ${t.options.adminMode?"hidden":""}>${t.t("techniqueHint")}</p>
              <div class="kb-choice-grid" id="kb-technique-grid"></div>
              <div id="kb-practitioner-box" class="kb-step1-followup" hidden>
                <div class="kb-section-title" style="font-size: 17px;">${t.t("qPrefer")}</div>
                <div class="kb-choice-grid" id="kb-practitioner-grid"></div>
              </div>
            </div>

            <div class="kb-step1-footer">
              <button type="button" class="kb-btn kb-btn-whatsapp" id="kb-btn-wa-existing" hidden>${t.t("openWhatsapp")}</button>
              <button type="button" class="kb-btn kb-btn-primary" id="kb-btn-next-1" disabled>${t.t("seeSlots")}</button>
            </div>
          </div>

          <!-- PASO 2: D\xCDA Y HORA -->
          <div class="kb-step-panel" id="kb-step-2">
            <div class="kb-section-title">${t.t("pickDay")}</div>
            <div class="kb-step2-pref-container" id="kb-step2-pref-container" style="display: none;">
              <button type="button" class="kb-step2-pref-pill" id="kb-step2-pref-pill" title="${t.t("changePref")}">
                <svg class="kb-step2-pref-icon" width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"></path><circle cx="12" cy="7" r="4"></circle></svg>
                <span class="kb-step2-pref-label">${t.t("prefTag")}</span>
                <strong class="kb-step2-pref-val" id="kb-step2-pref-val"></strong>
                <span class="kb-step2-pref-change">(${t.t("changePref")})</span>
              </button>
            </div>
            <div class="kb-section-desc" id="kb-slots-subtitle" style="display: none;"></div>

            <label class="kb-slots-label">${t.t("daysLabel")}</label>
            <div class="kb-date-scroll" id="kb-date-carousel"></div>

            <label class="kb-slots-label" id="kb-slots-grid-title">${t.t("slotsLabel")}</label>
            <div id="kb-slots-container">
              <div id="kb-slots-loading" class="kb-state-box" style="display: none;">
                <div class="kb-spinner"></div>
                <span>${t.t("loading")}</span>
              </div>
              <div id="kb-slots-empty" class="kb-state-box" style="display: none;">
                <span>${t.t("emptyDay")}</span>
              </div>
              <div id="kb-slots-error" class="kb-state-box kb-state-box-error" role="alert" style="display: none;">
                <span id="kb-slots-error-text" class="kb-slots-error-title">${t.t("slotError")}</span>
                <p id="kb-slots-error-fallback" class="kb-slots-error-fallback">${t.t("slotFallbackText")}</p>
                <div class="kb-slots-error-actions">
                  <button type="button" class="kb-btn kb-btn-whatsapp kb-btn-whatsapp-primary" id="kb-btn-fallback-whatsapp">${t.t("slotFallbackBtn")}</button>
                  <button type="button" class="kb-btn kb-btn-secondary" id="kb-btn-retry-slots">${t.t("retry")}</button>
                </div>
              </div>
              <div class="kb-slots-grid" id="kb-slots-grid"></div>
            </div>

            <div class="kb-actions">
              <button class="kb-btn kb-btn-secondary" id="kb-btn-prev-2">${t.t("back")}</button>
              <button class="kb-btn kb-btn-primary" id="kb-btn-next-2" disabled>${t.t("toData")}</button>
            </div>
          </div>

          <!-- PASO 3: FORMULARIO -->
          <div class="kb-step-panel" id="kb-step-3">
            <div class="kb-section-title">${t.t("dataTitle")}</div>
            <div class="kb-section-desc">${t.t("dataDesc")}</div>

            <div class="kb-radio-group" ${t.options.adminMode?'style="display:none"':""}>
              <div class="kb-radio-title">\xBFPara qui\xE9n es el turno?</div>
              <div class="kb-radio-options">
                <label class="kb-radio-label">
                  <input type="radio" name="kb-for-whom" id="kb-radio-self" value="self" checked>
                  <span>Para m\xED</span>
                </label>
                <label class="kb-radio-label">
                  <input type="radio" name="kb-for-whom" id="kb-radio-other" value="other">
                  <span>Para otra persona</span>
                </label>
              </div>
            </div>

            <div id="kb-third-party-box" style="display: none; margin-bottom: 16px; padding: 12px; background: #f0fdf4; border-radius: 8px; border: 1px solid #bbf7d0;">
              <div style="font-size: 12px; font-weight: 700; color: #166534; margin-bottom: 10px; text-transform: uppercase;">Tus datos (quien agenda el turno):</div>
              <div class="kb-form-group" style="margin-bottom: 8px;">
                <label for="kb-input-contacto-nombre">Tu Nombre y Apellido *</label>
                <input type="text" id="kb-input-contacto-nombre" placeholder="Ej: Laura G\xF3mez" maxlength="100" autocomplete="name">
                <div class="kb-field-error" id="kb-err-contacto-nombre" role="alert" aria-live="assertive" hidden></div>
              </div>
              <div class="kb-form-row">
                <div class="kb-form-group" style="margin-bottom: 8px;">
                  <label for="kb-input-contacto-telefono">Tu Tel\xE9fono / WhatsApp *</label>
                  <input type="tel" id="kb-input-contacto-telefono" placeholder="${t.t("phonePh")}" maxlength="24" inputmode="tel" autocomplete="tel">
                  <div class="kb-field-error" id="kb-err-contacto-telefono" role="alert" aria-live="assertive" hidden></div>
                </div>
                <div class="kb-form-group" style="margin-bottom: 8px;">
                  <label for="kb-input-contacto-notas">Relaci\xF3n o rol (opcional)</label>
                  <input type="text" id="kb-input-contacto-notas" placeholder="Ej: C\xF3nyuge, Hijo/a, Secretaria" maxlength="80">
                </div>
              </div>
              <small style="color: #64748b; font-size: 12px; display: block;">Te enviaremos el comprobante y podr\xE1s consultar o anular el turno cuando lo necesites.</small>
            </div>

            <div id="kb-patient-header" style="display: none; font-size: 12px; font-weight: 700; color: #1e293b; margin-bottom: 10px; text-transform: uppercase;">Datos del paciente (quien asistir\xE1 a la sesi\xF3n):</div>

            <div class="kb-form-group">
              <label for="kb-input-nombre" id="kb-label-nombre">${t.t("name")}</label>
              <input type="text" id="kb-input-nombre" placeholder="${t.t("namePh")}" maxlength="100" autocomplete="name" required>
              <div class="kb-field-error" id="kb-err-nombre" role="alert" aria-live="assertive" hidden></div>
            </div>

            <div class="kb-form-group">
              <label for="kb-input-email">${t.t("email")}</label>
              <input type="email" id="kb-input-email" placeholder="${t.t("emailPh")}" maxlength="120" inputmode="email" autocapitalize="off" spellcheck="false" required autocomplete="email">
              <div class="kb-field-error" id="kb-err-email" role="alert" aria-live="assertive" hidden></div>
            </div>

            <div class="kb-form-row">
              <div class="kb-form-group" id="kb-group-telefono">
                <label for="kb-input-telefono" id="kb-label-telefono">${t.t("phone")}</label>
                <input type="tel" id="kb-input-telefono" placeholder="${t.t("phonePh")}" maxlength="24" inputmode="tel" autocomplete="tel" required>
                <div class="kb-field-error" id="kb-err-telefono" role="alert" aria-live="assertive" hidden></div>
                <label id="kb-wrap-no-phone" class="kb-checkbox-label" style="display: none; align-items: center; gap: 8px; margin-top: 8px; font-size: 13px; color: #475569; cursor: pointer;">
                  <input type="checkbox" id="kb-check-no-phone">
                  <span>No tiene celular propio (usar mi n\xFAmero de WhatsApp)</span>
                </label>
              </div>
              <div class="kb-form-group">
                <label for="kb-input-dni" id="kb-label-dni">${t.options.adminMode?t.t("dniOptionalLabel"):t.t("dni")}</label>
                <input type="text" id="kb-input-dni" placeholder="${t.options.adminMode?t.t("dniOptionalPh"):t.t("dniPh")}" maxlength="20"${t.options.adminMode?"":" required"}>
                <div class="kb-field-error" id="kb-err-dni" role="alert" aria-live="assertive" hidden></div>
              </div>
            </div>

            <div class="kb-actions">
              <button class="kb-btn kb-btn-secondary" id="kb-btn-prev-3">${t.t("back")}</button>
              <button class="kb-btn kb-btn-primary" id="kb-btn-submit">${t.t("confirm")}</button>
            </div>
            <p class="kb-privacy-notice">
              ${t.t("privacyNoticeBefore")}<a href="${t.t("privacyUrl")}" target="_blank" rel="noopener noreferrer">${t.t("privacyPolicyLabel")}</a>${t.t("privacyNoticeAfter")}
            </p>
          </div>

          <!-- PASO 4: CONFIRMACI\xD3N -->
          <div class="kb-step-panel" id="kb-step-4">
            <div class="kb-success-card">
              <div class="kb-success-icon">\u2713</div>
              <div class="kb-success-title" id="kb-success-title">${t.t("success")}</div>
              <p id="kb-success-subtitle" style="color: var(--kin-text-muted);">${t.t("saved")}</p>

              <div class="kb-summary-box" id="kb-success-summary"></div>

              <div class="kb-calendar-sync-box" id="kb-calendar-sync-box">
                <div class="kb-calendar-sync-header">
                  <span class="kb-calendar-sync-icon" aria-hidden="true">\u{1F4C5}</span>
                  <div>
                    <div class="kb-calendar-sync-title">${t.t("saveCal")}</div>
                    <div class="kb-calendar-sync-subtitle">${t.t("saveCalSub")}</div>
                  </div>
                </div>
                <div class="kb-calendar-sync-actions">
                  <a href="#" target="_blank" rel="noopener noreferrer" class="kb-btn-cal kb-btn-cal-google" id="kb-btn-cal-google">
                    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" aria-hidden="true">
                      <path d="M19 4h-1V2h-2v2H8V2H6v2H5c-1.11 0-2 .89-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V6c0-1.11-.89-2-2-2zm0 16H5V9h14v11z" fill="#4285F4"/>
                      <rect x="7" y="11" width="3" height="3" fill="#EA4335"/><rect x="11" y="11" width="3" height="3" fill="#FBBC05"/><rect x="15" y="11" width="3" height="3" fill="#34A853"/>
                    </svg>
                    <span>Google Calendar</span>
                  </a>
                  <button type="button" class="kb-btn-cal kb-btn-cal-ics" id="kb-btn-cal-ics">
                    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="3" y="4" width="18" height="18" rx="2" ry="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg>
                    <span id="kb-btn-cal-ics-text">Apple / Outlook (.ics)</span>
                  </button>
                </div>
              </div>

              <div class="kb-clinic-rules" id="kb-success-clinic-rules" style="display: none;">
                <h4>${t.t("rulesTitle")}</h4>
                <ul><li>${t.t("rulesAddr")}</li><li>${t.t("rulesTime")}</li><li>${t.t("rulesCompany")}</li><li>${t.t("rulesClothes")}</li><li>${t.t("rulesStudies")}</li></ul>
                <div style="margin-top: 14px; text-align: center;"><a href="https://maps.app.goo.gl/urpkh4HYe7dSdjPS9" target="_blank" rel="noopener" class="kb-btn kb-btn-primary" style="display: inline-flex; text-decoration: none;">${t.t("maps")}</a></div>
              </div>

              ${t.options.isModal?`
                <div style="margin-top: 22px; text-align: center;">
                  <button type="button" class="kb-btn kb-btn-secondary" data-action="close-modal" style="width: auto; padding: 10px 28px; font-weight: 600;">${t.t("done")}</button>
                </div>
              `:`
                <div style="margin-top: 22px; text-align: center;">
                  <button type="button" class="kb-btn kb-btn-secondary" data-action="reset-widget" style="width: auto; padding: 10px 28px; font-weight: 600;">${t.t("newBooking")}</button>
                </div>
              `}
            </div>
          </div>

        </div>
      </div>
    `}return{buildWidgetTemplate:e}});
